window.__ttscBoot.push("/**\n * TTSC Premium Notification System\n * Handles success, error, warning and info toasts with modern UI.\n * Globally intercepts window.alert to provide elegant toast notifications system-wide.\n */\n\n(function() {\n    'use strict';\n\n    const TTSCNotify = {\n        container: null,\n        \n        init: function() {\n            if (this.container && document.body.contains(this.container)) return;\n            \n            this.container = document.getElementById('ttsc-notification-container');\n            if (!this.container) {\n                this.container = document.createElement('div');\n                this.container.id = 'ttsc-notification-container';\n                document.body.appendChild(this.container);\n            }\n        },\n\n        show: function(options) {\n            this.init();\n            \n            const {\n                type = 'info',\n                title = '',\n                message = '',\n                duration = 4500,\n                icon = null\n            } = options;\n\n            const toast = document.createElement('div');\n            toast.className = `ttsc-notification ttsc-notification-${type}`;\n            \n            const defaultIcons = {\n                success: 'fa-circle-check',\n                error: 'fa-circle-xmark',\n                warning: 'fa-triangle-exclamation',\n                info: 'fa-circle-info',\n                destructive: 'fa-circle-xmark'\n            };\n\n            const selectedIcon = icon || defaultIcons[type] || defaultIcons.info;\n\n            toast.innerHTML = `\n                <div class=\"ttsc-notification-icon\">\n                    <i class=\"fa-light ${selectedIcon}\"></i>\n                </div>\n                <div class=\"ttsc-notification-content\">\n                    ${title ? `<div class=\"ttsc-notification-title\">${title}</div>` : ''}\n                    <div class=\"ttsc-notification-message\">${message}</div>\n                </div>\n                <div class=\"ttsc-notification-close\" style=\"cursor:pointer;\" title=\"Fechar\">\n                    <i class=\"fa-light fa-xmark text-xs\"></i>\n                </div>\n                <div class=\"ttsc-notification-progress\" style=\"animation: ttsc-notification-progress-anim ${duration}ms linear forwards\"></div>\n            `;\n\n            this.container.appendChild(toast);\n\n            // Trigger animation\n            requestAnimationFrame(() => {\n                toast.classList.add('show');\n            });\n\n            // Close button\n            const closeBtn = toast.querySelector('.ttsc-notification-close');\n            if (closeBtn) closeBtn.onclick = () => this.hide(toast);\n\n            // Auto hide\n            if (duration > 0) {\n                setTimeout(() => this.hide(toast), duration);\n            }\n\n            return toast;\n        },\n\n        hide: function(toast) {\n            if (!toast) return;\n            toast.classList.add('hide');\n            toast.classList.remove('show');\n            setTimeout(() => {\n                if (toast.parentNode) {\n                    toast.parentNode.removeChild(toast);\n                }\n            }, 400);\n        },\n\n        success: function(message, title = 'Sucesso') {\n            return this.show({ type: 'success', message, title, icon: 'fa-circle-check' });\n        },\n\n        error: function(message, title = 'Erro') {\n            return this.show({ type: 'error', message, title, icon: 'fa-circle-xmark' });\n        },\n\n        warning: function(message, title = 'Aviso') {\n            return this.show({ type: 'warning', message, title, icon: 'fa-triangle-exclamation' });\n        },\n\n        info: function(message, title = 'Informa\u00e7\u00e3o') {\n            return this.show({ type: 'info', message, title, icon: 'fa-circle-info' });\n        },\n        \n        destructive: function(message, title = 'Aten\u00e7\u00e3o') {\n            return this.show({ type: 'destructive', message, title, icon: 'fa-circle-xmark' });\n        }\n    };\n\n    // Global accessibility\n    window.TTSCNotify = TTSCNotify;\n\n    // Toastr Polyfill/Wrapper for backward compatibility\n    window.toastr = {\n        success: (m, t) => TTSCNotify.success(m, t),\n        error: (m, t) => TTSCNotify.error(m, t),\n        warning: (m, t) => TTSCNotify.warning(m, t),\n        info: (m, t) => TTSCNotify.info(m, t),\n        destructive: (m, t) => TTSCNotify.destructive(m, t)\n    };\n\n    // Toast.show() and showToast()\n    window.showToast = function(message, type = 'info', title = null, duration = 4500) {\n        if (TTSCNotify[type]) {\n            return TTSCNotify[type](message, title);\n        } else {\n            return TTSCNotify.info(message, title);\n        }\n    };\n\n    window.Toast = {\n        show: window.showToast\n    };\n\n    // ========================================================\n    // GLOBAL WINDOW.ALERT INTERCEPTOR\n    // Replaces all native browser alert() dialogs with modern toasts\n    // ========================================================\n    window.alert = function(msg) {\n        if (msg === undefined || msg === null) return;\n        const str = String(msg);\n        const lower = str.toLowerCase();\n        let type = 'info';\n        let title = 'TotusTuus SoftCloud';\n\n        if (lower.includes('sucesso') || lower.includes('gravad') || lower.includes('salvo') || lower.includes('renovad') || lower.includes('atualizad') || lower.includes('sincronizad') || lower.includes('conclu\u00edd')) {\n            type = 'success';\n            title = 'Sucesso';\n        } else if (lower.includes('erro') || lower.includes('falha') || lower.includes('invalid') || lower.includes('inv\u00e1lid') || lower.includes('negad') || lower.includes('recusad')) {\n            type = 'error';\n            title = 'Erro';\n        } else if (lower.includes('aviso') || lower.includes('aten\u00e7\u00e3o') || lower.includes('cuidado') || lower.includes('revogad') || lower.includes('encerrad') || lower.includes('silenciad') || lower.includes('exclu')) {\n            type = 'warning';\n            title = 'Aviso';\n        }\n\n        TTSCNotify.show({\n            type: type,\n            title: title,\n            message: str,\n            duration: 4500\n        });\n    };\n\n})();\n");

